import subprocess, pathlib, os
os.makedirs('system',exist_ok=True)
header=lambda obj: f'''FoamFile
{{
    format ascii;
    class dictionary;
    object {obj};
}}
'''
pathlib.Path('system/controlDict').write_text(header('controlDict')+'''application checkMesh;
startFrom startTime;
startTime 0;
stopAt endTime;
endTime 1;
deltaT 1;
writeControl timeStep;
writeInterval 1;
''')
pathlib.Path('system/fvSchemes').write_text(header('fvSchemes')+'''ddtSchemes { default steadyState; }
gradSchemes { default Gauss linear; }
divSchemes { default none; }
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }
''')
pathlib.Path('system/fvSolution').write_text(header('fvSolution')+'''solvers {}
''')
r=subprocess.run(['gmshToFoam','sealLeakage.msh'],text=True,capture_output=True); print(r.stdout[-1000:]); r.check_returncode()
cm=subprocess.run(['checkMesh'],text=True,capture_output=True); print(cm.stdout); print(cm.stderr); print('checkMesh return',cm.returncode)
assert cm.returncode==0 and 'Mesh OK' in cm.stdout
